import{_ as f,b as e,c as o,d as a,t as v,C as l,u as b}from"./index-I5uTs6b4.js";const n={class:"level-page"},i={class:"level-content"},p={class:"level-title"},u={__name:"Level15",props:{id:{type:String,required:!0}},setup(d){const s=b();function c(){sessionStorage.setItem("skipIntro","1"),s.push("/")}return(r,t)=>(e(),o("div",n,[a("button",{class:"back-btn",onClick:c},"← Back to Index"),a("div",i,[a("h1",p,"SI-"+v(d.id),1),t[0]||(t[0]=l('<p class="level-name" data-v-cfdb3f61>&quot;幻痛&quot;</p><p class="epigraph-top" data-v-cfdb3f61>&quot;歌舞升平之中，也不要忘记永恒的伤痛&quot;</p><div class="section" data-v-cfdb3f61><h2 data-v-cfdb3f61>生存难度：运变 宜居 → 4</h2><div class="difficulty" data-v-cfdb3f61><ul class="class-list" data-v-cfdb3f61><li data-v-cfdb3f61><span class="class-bullet mental" data-v-cfdb3f61></span> 不定的精神影响</li><li data-v-cfdb3f61><span class="class-bullet entity" data-v-cfdb3f61></span> 传染性效应</li><li data-v-cfdb3f61><span class="class-bullet safe" data-v-cfdb3f61></span> 充足的资源</li></ul></div></div><div class="section" data-v-cfdb3f61><h2 data-v-cfdb3f61>层级结构</h2><p data-v-cfdb3f61>由无数个大型夜店以区块为单位挤压、拼接而成，每个夜店内存在主厅、舞池、BAR、温泉区、客房、包厢等功能区。夜店之间形成连廊式的缓冲区。不同功能区装潢不一，但共同的特点是：<strong data-v-cfdb3f61>白底红框黑图案的&quot;手机静音&quot;提示</strong>。</p><p data-v-cfdb3f61><strong data-v-cfdb3f61>主厅：</strong>大型铁框灯架，大型 LED 屏，大型 DJ 台，地势高于舞池 2 米，蓝色系射灯。<strong data-v-cfdb3f61>舞池：</strong>地势基准点，紫色、绿色、黄色系射灯。<strong data-v-cfdb3f61>BAR：</strong>1m 地势，暖黄色地面灯带，卡座，吧台。</p></div><div class="section" data-v-cfdb3f61><h2 data-v-cfdb3f61>特殊实体 &quot;电话&quot;</h2><p data-v-cfdb3f61>随机发出特定的&quot;电话铃声&quot;并在周围一定范围内引发认知污染。外形为任意形制的固定或移动通讯设备。流浪者在认知干扰产生的幻觉中&quot;死亡&quot;会使身上的通讯设备转化为&quot;电话&quot;，同时流浪者大脑停止活动。</p></div><div class="section" data-v-cfdb3f61><h2 data-v-cfdb3f61>SI-15 相关效应</h2><p data-v-cfdb3f61><strong data-v-cfdb3f61>半孤立效应：</strong>流浪者以 1 至 5 名为一个单位被孤立。<strong data-v-cfdb3f61>&quot;安全时间&quot;效应：</strong>流浪者切入 SI-15 时会有一段时间不受到认知干扰影响。</p></div><section class="sub-level" data-v-cfdb3f61><div class="sub-tag" data-v-cfdb3f61>子层级 I</div><p class="sub-name" data-v-cfdb3f61>夜店</p><p data-v-cfdb3f61>如上所述。</p></section><section class="sub-level dead-zone" data-v-cfdb3f61><div class="sub-tag dead-tag" data-v-cfdb3f61>子层级 II</div><p class="sub-name" data-v-cfdb3f61>医院</p><p data-v-cfdb3f61>无 I 中的污染类实体，只有无法清理的尸体和定时刷新的医疗物资。该实体（注：指医院中的实体）会主动攻击流浪者，攻击欲望高，且部分实体会伪装成医护人员潜伏各处。请注意分辨。该层分为一、二、三楼三层，每一层成模块化无限延展。从 I 中切出有概率进入 II。从 II 中切出一定会来到其他 SI 层级。</p></section><div class="epigraph-bottom" data-v-cfdb3f61><p data-v-cfdb3f61>那都是看到新闻后，他们的家人朋友打来而响起的</p><p data-v-cfdb3f61>舞池里的尸体堆里密密麻麻的电话铃声</p><p data-v-cfdb3f61>那都是仇恨的枪声过后</p><p data-v-cfdb3f61>你所能听到的无数幻痛</p></div>',9))])]))}},q=f(u,[["__scopeId","data-v-cfdb3f61"]]);export{q as default};
